  "type": "object",
  "properties": {
    "clauses": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "clause_type": {
            "type": "string",
            "enum": [
              "Governing Law",
              "Termination For Convenience",
              "Cap On Liability",
              "Renewal Term",
              "Anti-Assignment"
            ]
          },
          "seq_no": { "type": "integer" },
          "clause_text": { "type": "string" },
          "confidence": { "type": "number" },
          "reasoning": { "type": "string" }
        },
        "required": ["clause_type", "seq_no", "clause_text", "confidence", "reasoning"],
        "additionalProperties": false
      }
    }
  },
  "required": ["clauses"],
  "additionalProperties": false
}

