/**
 * WF3 - AI Risk Analysis
 * Node: "Parse & Validate"  (Code node, Mode = Run Once for All Items)
 *
 * Repo copy: workflows/code/wf3_parse_validate.js
 * Version 2 - segment resolution is now evidence-based.
 *
 * WHAT CHANGED FROM v1
 * v1 trusted the model's [SEG n] marker to identify the source segment.
 * On the first real run, 2 of 5 clauses cited a seq_no that was not in
 * their own batch, so segment_id and both character offsets came back
 * null. Batching buys speed at the cost of the model having to count
 * markers correctly, and it does not always manage it.
 *
 * v2 searches the batch's segments for the quoted text and uses
 * whichever segment actually contains it. The model's seq_no is only a
 * fallback hint. Traceability no longer depends on the model counting.
 *
 * OUTPUT: one item per clause row, ready for INSERT.
 */

const PROMPT_VERSION = 'v1';   // the PROMPT is unchanged; only this node moved
const MODEL = 'gpt-4o-mini';

const CLAUSE_TYPES = [
  'Governing Law',
  'Termination For Convenience',
  'Cap On Liability',
  'Renewal Term',
  'Anti-Assignment',
];

/** Collapse whitespace so a line-wrap difference is not read as a mismatch. */
const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();

// ---------------------------------------------------------------
// Lookup: segment_id -> text and absolute offset in full_text.
// Built from Fetch Segments, never from anything the model reported.
// ---------------------------------------------------------------
const segmentById = new Map();
for (const row of $('Fetch Segments').all()) {
  const s = row.json;
  if (!s || !s.segment_text) continue;
  segmentById.set(Number(s.segment_id), {
    text: s.segment_text,
    textNorm: norm(s.segment_text),
    char_start: Number(s.char_start),
    seq_no: Number(s.seq_no),
  });
}

const batches = $('Build Batches').all();
const documentId = Number(batches[0].json.document_id);

/**
 * Response shape is output[0].content[0].text.clauses, where .text is an
 * OBJECT because JSON Schema mode already parsed it. The fallbacks cover
 * the other shapes n8n returns under different Simplify settings, so a
 * settings change cannot silently produce zero clauses.
 */
function extractClauses(json) {
  const candidates = [
    json?.output?.[0]?.content?.[0]?.text,
    json?.message?.content,
    json?.content,
    json,
  ];

  for (const c of candidates) {
    if (!c) continue;
    if (Array.isArray(c?.clauses)) return c.clauses;
    if (typeof c === 'string') {
      try {
        const parsed = JSON.parse(c);
        if (Array.isArray(parsed?.clauses)) return parsed.clauses;
      } catch (e) { /* not JSON, try next candidate */ }
    }
  }
  return [];
}

/**
 * Find which segment of this batch actually contains the quoted text.
 *
 * Order matters:
 *   1. Exact substring in the segment the model named. Cheapest, and
 *      correct whenever the model counted right.
 *   2. Exact substring in any other segment of the batch. Catches
 *      mis-attribution while still proving the quote is verbatim.
 *   3. Whitespace-normalised match anywhere in the batch. Proves the
 *      words are right even if line wrapping differs - but offsets
 *      cannot be trusted, so they are left null rather than guessed.
 *
 * Returning offsets we are not sure of would be worse than returning
 * none: Phase 4 error analysis would follow them to the wrong place.
 */
function locate(clauseText, batchSegments, hintedSeqNo) {
  const hinted = batchSegments.find(s => Number(s.seq_no) === Number(hintedSeqNo));
  const ordered = hinted
    ? [hinted, ...batchSegments.filter(s => s !== hinted)]
    : batchSegments;

  // Passes 1 and 2: exact substring.
  for (const s of ordered) {
    const seg = segmentById.get(Number(s.segment_id));
    if (!seg) continue;
    const idx = seg.text.indexOf(clauseText);
    if (idx !== -1) {
      return {
        segment_id: Number(s.segment_id),
        char_start: seg.char_start + idx,
        char_end: seg.char_start + idx + clauseText.length,
        verbatim_ok: true,
        attribution: hinted && Number(s.segment_id) === Number(hinted.segment_id)
          ? 'model'          // model named the right segment
          : 'recovered',     // model was wrong, text search fixed it
      };
    }
  }

  // Pass 3: whitespace-tolerant.
  const needle = norm(clauseText);
  for (const s of ordered) {
    const seg = segmentById.get(Number(s.segment_id));
    if (!seg) continue;
    if (seg.textNorm.includes(needle)) {
      return {
        segment_id: Number(s.segment_id),
        char_start: null,
        char_end: null,
        verbatim_ok: true,
        attribution: 'normalised',
      };
    }
  }

  // Nowhere in the batch: the model paraphrased despite instruction.
  return {
    segment_id: null,
    char_start: null,
    char_end: null,
    verbatim_ok: false,
    attribution: 'not_found',
  };
}

const rows = [];
const seen = new Set();
const foundTypes = new Set();

items.forEach((item, index) => {
  const clauses = extractClauses(item.json);

  // n8n preserves item order, so position links an LLM result back to
  // the batch that produced it. The LLM output carries no batch_no.
  const batch = batches[index]?.json;
  if (!batch) return;

  const batchSegments = batch.segments || [];

  for (const c of clauses) {
    const clauseType = (c.clause_type || '').trim();
    const clauseText = (c.clause_text || '').trim();

    // The JSON Schema enum should make both impossible. Checked anyway:
    // a bad clause_type would fail the DB CHECK and abort the insert.
    if (!CLAUSE_TYPES.includes(clauseType) || !clauseText) continue;

    const key = `${clauseType}::${norm(clauseText)}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const found = locate(clauseText, batchSegments, c.seq_no);

    let confidence = Number(c.confidence);
    if (!Number.isFinite(confidence)) confidence = 0.5;
    confidence = Math.min(1, Math.max(0, confidence));

    foundTypes.add(clauseType);

    rows.push({
      json: {
        document_id: documentId,
        segment_id: found.segment_id,
        clause_type: clauseType,
        clause_text: clauseText,
        char_start: found.char_start,
        char_end: found.char_end,
        confidence: Number(confidence.toFixed(3)),
        is_absent: false,
        reasoning: c.reasoning || null,
        verbatim_ok: found.verbatim_ok,
        attribution: found.attribution,   // model | recovered | normalised | not_found
        model: MODEL,
        prompt_version: PROMPT_VERSION,
        batch_no: Number(batch.batch_no),
      },
    });
  }
});

// ---------------------------------------------------------------
// Absence rows.
//
// Decided here because this node is the first point that has seen
// every batch, so it can tell "not in this batch" from "not in this
// document". Without these rows, "the model said no" and "WF3 crashed
// early" are indistinguishable in the database, which silently
// inflates false negatives in the Phase 4 recall figure.
// ---------------------------------------------------------------
for (const type of CLAUSE_TYPES) {
  if (foundTypes.has(type)) continue;
  rows.push({
    json: {
      document_id: documentId,
      segment_id: null,
      clause_type: type,
      clause_text: null,       // DB CHECK requires NULL when is_absent
      char_start: null,
      char_end: null,
      confidence: null,
      is_absent: true,
      reasoning: 'Not found in any batch of this document.',
      verbatim_ok: true,
      attribution: 'absent',
      model: MODEL,
      prompt_version: PROMPT_VERSION,
      batch_no: null,
    },
  });
}

return rows;

/**
 * WF3 - AI Risk Analysis
 * Node: "Score Risk"  (Code node, Mode = Run Once for All Items)
 *
 * Repo copy: workflows/code/wf3_score_risk.js
 *
 * Turns each extracted clause into a risk_score (0..1) and a
 * risk_level, and decides whether it needs a human.
 *
 * WHY THIS IS RULES AND NOT ANOTHER LLM CALL
 * Ask a model to score risk and the same clause scores 0.6 today and
 * 0.75 next week, with no explanation for either. A rules table gives a
 * number that can be defended - "an absent liability cap scores 0.90
 * because the policy config says so" - and makes WF6's aggregates
 * comparable across runs. It is also free and instant.
 *
 * The scores below are a starting policy, not received wisdom. They are
 * in one block at the top precisely so they can be argued with and
 * changed without touching the logic.
 */

// ===============================================================
// POLICY CONFIG
// ===============================================================

/**
 * BASE_RISK - inherent risk of each clause type when present and normal.
 * Governing Law is low: unfavourable law is inconvenient, not dangerous.
 * Cap On Liability is higher because the amount matters enormously.
 */
const BASE_RISK = {
  'Governing Law': 0.20,
  'Termination For Convenience': 0.50,
  'Cap On Liability': 0.55,
  'Renewal Term': 0.40,
  'Anti-Assignment': 0.35,
};

/**
 * ABSENT_RISK - risk when the clause type is MISSING from the contract.
 *
 * Absence is not the same as low risk, and for some types it is worse
 * than presence. No liability cap means unlimited exposure. No
 * anti-assignment clause means the counterparty can hand the contract
 * to a competitor. A missing governing law clause, by contrast, is a
 * gap the law itself will fill.
 *
 * This asymmetry is the whole reason is_absent rows exist.
 */
const ABSENT_RISK = {
  'Governing Law': 0.30,
  'Termination For Convenience': 0.25,
  'Cap On Liability': 0.90,
  'Renewal Term': 0.45,
  'Anti-Assignment': 0.60,
};

/**
 * MODIFIERS - textual signals that adjust the base score.
 * Applied only to clauses that are present. Cumulative, then clamped.
 */
const MODIFIERS = [
  // Automatic renewal with a short objection window is a classic trap.
  { types: ['Renewal Term'], pattern: /automatic(ally)?\s+renew/i, delta: +0.20,
    note: 'auto-renews' },
  { types: ['Renewal Term'], pattern: /\b(thirty|30)\s*\(?30?\)?\s*days?\b/i, delta: +0.10,
    note: 'short notice window' },

  // Unlimited or carved-out liability.
  { types: ['Cap On Liability'], pattern: /unlimited|no\s+limit|shall\s+not\s+be\s+limited/i,
    delta: +0.30, note: 'liability not truly capped' },
  { types: ['Cap On Liability'], pattern: /fees\s+paid|amounts?\s+paid/i, delta: -0.15,
    note: 'capped at fees paid' },

  // One-sided termination.
  { types: ['Termination For Convenience'], pattern: /sole\s+discretion/i, delta: +0.15,
    note: 'sole discretion' },
  { types: ['Termination For Convenience'], pattern: /immediately|without\s+notice/i,
    delta: +0.20, note: 'no notice period' },

  // Assignment restrictions that bite on ordinary corporate events.
  { types: ['Anti-Assignment'], pattern: /change\s+of\s+control/i, delta: +0.20,
    note: 'change of control triggers' },
  { types: ['Anti-Assignment'], pattern: /not\s+be\s+unreasonably\s+withheld/i, delta: -0.15,
    note: 'consent not unreasonably withheld' },
];

/** Score bands. risk_level must match the DB CHECK in migration 003. */
const RISK_BANDS = [
  { max: 0.35, level: 'low' },
  { max: 0.60, level: 'medium' },
  { max: 0.85, level: 'high' },
  { max: 1.01, level: 'critical' },
];

/**
 * CONFIDENCE_THRESHOLD - below this, a human reviews it (WF4).
 *
 * 0.70 is a placeholder. The project plan says tau is decided
 * empirically in Phase 2 from the DEV set only. Do not tune this
 * against holdout data - that would make the final number self-graded.
 */
const CONFIDENCE_THRESHOLD = 0.70;

// ===============================================================
// LOGIC
// ===============================================================

const clamp = (n) => Math.min(1, Math.max(0, n));

function bandFor(score) {
  for (const b of RISK_BANDS) {
    if (score < b.max) return b.level;
  }
  return 'critical';
}

return items.map((item) => {
  const c = item.json;
  const type = c.clause_type;

  let score;
  const notes = [];

  if (c.is_absent) {
    score = ABSENT_RISK[type] ?? 0.50;
    notes.push('clause absent');
  } else {
    score = BASE_RISK[type] ?? 0.50;

    const text = c.clause_text || '';
    for (const mod of MODIFIERS) {
      if (!mod.types.includes(type)) continue;
      if (mod.pattern.test(text)) {
        score += mod.delta;
        notes.push(mod.note);
      }
    }

    // A shaky extraction is itself a risk: if the model is unsure it
    // read the clause correctly, the clause deserves more attention,
    // not less. Small nudge only - confidence is reported separately
    // and should not be double-counted into the risk figure.
    if (Number(c.confidence) < 0.60) {
      score += 0.05;
      notes.push('low extraction confidence');
    }
  }

  score = clamp(score);

  // Absent clauses have NULL confidence, so they cannot be compared
  // against the threshold. They are routed for review on their own
  // merit: a missing high-risk clause is exactly what a lawyer should
  // be told about.
  const needsReview = c.is_absent
    ? score >= 0.60
    : Number(c.confidence) < CONFIDENCE_THRESHOLD;

  return {
    json: {
      ...c,
      risk_score: Number(score.toFixed(3)),
      risk_level: bandFor(score),
      risk_notes: notes.join('; ') || null,
      needs_review: needsReview,
      review_status: needsReview ? 'pending_review' : 'auto',
      confidence_threshold: CONFIDENCE_THRESHOLD,
    },
  };
});

parameters.query:
DELETE FROM clauses
WHERE document_id = $1
  AND review_status = 'auto';

