/**
 * WF3 - Node: "Restore Rows" (Code, Run Once for All Items)
 * Repo copy: workflows/code/wf3_restore_rows.js
 *
 * A Postgres node REPLACES its input with its own result. "Delete Old
 * Clauses" returns nothing, so without this node the five scored clause
 * rows would be gone and the INSERT below would have nothing to write.
 *
 * This reaches back past the Postgres node and picks the rows up again.
 *
 * It also pre-builds the parameter array for the INSERT. Building it
 * here rather than as a 14-item expression in the n8n UI keeps the
 * ordering readable and reviewable - a misplaced comma in that field is
 * very hard to spot and would silently write values into wrong columns.
 */

return $('Score Risk').all().map((row) => {
  const c = row.json;

  // Metadata that has no dedicated column lives in extracted_fields.
  // JSONB is why this can evolve without another migration.
  const extracted = {
    reasoning: c.reasoning,
    risk_notes: c.risk_notes,
    attribution: c.attribution,
    verbatim_ok: c.verbatim_ok,
    batch_no: c.batch_no,
    confidence_threshold: c.confidence_threshold,
  };

  return {
    json: {
      ...c,
      params: [
        c.document_id,
        c.segment_id,
        c.clause_type,
        c.clause_text,
        c.char_start,
        c.char_end,
        c.confidence,
        c.review_status,
        c.is_absent,
        c.risk_score,
        c.risk_level,
        c.model,
        c.prompt_version,
        JSON.stringify(extracted),
      ],
    },
  };
});
